package br.com.sussmartcare.notification.infrastructure; import br.com.sussmartcare.notification.application.NotificationChannel; import br.com.sussmartcare.notification.domain.Notification; import org.slf4j.*; import org.springframework.stereotype.Component; @Component public class SmsNotificationChannel implements NotificationChannel {private static final Logger log=LoggerFactory.getLogger(SmsNotificationChannel.class);public boolean supports(String c){return "SMS".equalsIgnoreCase(c);}public void send(Notification n){log.info("notification_delivered_simulated adapter=SMS patient={} visit={} type={}",n.getPatientId(),n.getVisitId(),n.getType());}}
